#include <cstdio>
#include <algorithm>
#include <vector>
using namespace std;

const int INF = 0x3f3f3f3f;
const int mod = 1e9 + 7;

int main() {
    int n, w;
    scanf("%d%d", &n, &w);
    vector<int> costs(n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &costs[i]);
    }
    vector<int> dp(w + 10, 0);
    dp[0] = 1;
    for (int total = 1; total <= w; total++) {
        for (int j = 0; j < n; j++) {
            if (total >= costs[j]) {
                dp[total] = (dp[total] + dp[total - costs[j]]) % mod;
            }
        }
    }
    printf("%d\n", dp[w]);
    return 0;
}
